import {chromium} from 'playwright';

const URL = 'http://127.0.0.1:5179/';
const report = {};
const errors = [];

const browser = await chromium.launch({args: ['--no-sandbox']});
const context = await browser.newContext({viewport: {width: 1280, height: 800}, colorScheme: 'light'});
const page = await context.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => {
  if (m.type() === 'error' || m.type() === 'warning') errors.push(`console.${m.type()}: ${m.text()}`);
});

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('.cpu-chart canvas', {timeout: 15000});

// 1. Одна инстанция графика (StrictMode дважды монтирует эффект — не должно быть дублей)
report.uplotCount = await page.locator('.cpu-chart .uplot').count();
report.yagrThemeLight = await page.locator('.cpu-chart.yagr_theme_light').count();

// 2. Размер графика = размер контейнера
const boxes = async () => ({
  host: await page.locator('.cpu-chart').boundingBox(),
  card: await page.locator('.cpu-card').boundingBox(),
  uplot: await page.locator('.cpu-chart .uplot').boundingBox(),
});
report.sizeLight = await boxes();

// 3. Реальное время: кадры канваса меняются, и измеряем длинные задачи
await page.evaluate(() => {
  window.__long = 0;
  window.__frames = [];
  new PerformanceObserver((list) => {
    for (const e of list.getEntries()) window.__long += e.duration;
  }).observe({entryTypes: ['longtask']});
  let last = performance.now();
  const loop = (t) => {
    window.__frames.push(t - last);
    last = t;
    if (window.__frames.length < 900) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
});
const canvasHash = () =>
  page.evaluate(() => {
    const c = document.querySelector('.cpu-chart canvas');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let h = 0;
    for (let i = 0; i < d.length; i += 97) h = (h * 31 + d[i]) | 0;
    return h;
  });
const h1 = await canvasHash();
await page.waitForTimeout(7000); // 3+ новых сэмпла при шаге 2 с
const h2 = await canvasHash();
report.canvasChangedInRealtime = h1 !== h2;
report.longTasksMsOver7s = await page.evaluate(() => Math.round(window.__long));
const frames = await page.evaluate(() => window.__frames.slice(2));
frames.sort((a, b) => a - b);
report.frameMs = {median: +frames[Math.floor(frames.length / 2)].toFixed(1), p95: +frames[Math.floor(frames.length * 0.95)].toFixed(1), max: +frames[frames.length - 1].toFixed(1)};

await page.screenshot({path: '/tmp/pw-check/light.png', fullPage: true});

// 4. Hover: тултип и кроссхейр
const uBox = await page.locator('.cpu-chart .uplot .u-over').boundingBox();
await page.mouse.move(uBox.x + uBox.width * 0.6, uBox.y + uBox.height * 0.4);
await page.waitForTimeout(300);
report.tooltipVisible = await page.evaluate(() => {
  const el = document.querySelector('.cpu-chart .u-cursor-x, .cpu-chart .u-cursor-y');
  return !!el;
});
await page.screenshot({path: '/tmp/pw-check/light-hover.png', fullPage: true});
await page.mouse.move(0, 0);

// 5. Ресайз контейнера: график должен растянуться
await page.setViewportSize({width: 960, height: 620});
await page.waitForTimeout(600);
report.sizeSmall = await boxes();
await page.setViewportSize({width: 1440, height: 1000});
await page.waitForTimeout(600);
report.sizeBig = await boxes();

// 6. Смена темы ОС: график пересоздаётся, дублей нет, цвета дарк
await page.emulateMedia({colorScheme: 'dark'});
await page.waitForTimeout(800);
report.uplotCountDark = await page.locator('.cpu-chart .uplot').count();
report.yagrThemeDark = await page.locator('.cpu-chart.yagr_theme_dark').count();
report.surfaceDark = await page.evaluate(() => getComputedStyle(document.querySelector('.cpu-card')).backgroundColor);
await page.waitForTimeout(2500);
await page.screenshot({path: '/tmp/pw-check/dark.png', fullPage: true});

// 7. Возврат в светлую — ещё одна пересборка, без утечки
await page.emulateMedia({colorScheme: 'light'});
await page.waitForTimeout(800);
report.uplotCountBackLight = await page.locator('.cpu-chart .uplot').count();

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
await browser.close();

