args.content:
import {chromium} from 'playwright';

const URL = 'http://127.0.0.1:5180/';
const report = {};
const errors = [];

const browser = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
let alive = true;
browser.on('disconnected', () => { alive = false; });
const context = await browser.newContext({viewport: {width: 1280, height: 800}, colorScheme: 'light', locale: 'ru-RU'});
// Среда песочницы падает на загрузке webfont-ов; вырезаем @font-face из CSS, системный шрифт остаётся.
await context.route(/\.css(\?|$)/, async (route) => {
  const response = await route.fetch();
  const body = (await response.text()).replace(/@font-face\s*\{[^}]*\}/g, '');
  await route.fulfill({response, body, contentType: 'text/css'});
});
const page = await context.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => {
  if (m.type() === 'error' || m.type() === 'warning') errors.push(`console.${m.type()}: ${m.text().slice(0, 300)}`);
});

await page.goto(URL, {waitUntil: 'load', timeout: 30000});
await page.waitForSelector('.cpu-chart canvas', {timeout: 15000});
report.alive = alive;

// 1. Одна инстанция графика (в prod без StrictMode, но проверяем отсутствие дублей)
report.uplotCount = await page.locator('.cpu-chart .uplot').count();
report.themeClassLight = await page.locator('.cpu-chart.yagr_theme_light').count();

const boxes = async () => ({
  host: await page.locator('.cpu-chart').boundingBox(),
  card: await page.locator('.cpu-card').boundingBox(),
  uplot: await page.locator('.cpu-chart .uplot').boundingBox(),
});
report.sizeInitial = await boxes();

// 2. Реальное время: кадры канваса меняются; длинные задачи и кадры
await page.evaluate(() => {
  window.__long = 0;
  window.__frames = [];
  new PerformanceObserver((list) => {
    for (const e of list.getEntries()) window.__long += e.duration;
  }).observe({entryTypes: ['longtask']});
  let last = performance.now();
  const loop = (t) => {
    window.__frames.push(t - last);
    last = t;
    if (window.__frames.length < 400) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
});
const canvasHash = () =>
  page.evaluate(() => {
    const c = document.querySelector('.cpu-chart canvas');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let h = 0;
    for (let i = 0; i < d.length; i += 97) h = (h * 31 + d[i]) | 0;
    return h;
  });
const h1 = await canvasHash();
await page.waitForTimeout(7000);
const h2 = await canvasHash();
report.canvasChangedInRealtime = h1 !== h2;
report.longTasksMsOver7s = await page.evaluate(() => Math.round(window.__long));
const frames = await page.evaluate(() => window.__frames.slice(2));
frames.sort((a, b) => a - b);
report.frameMs = {
  median: +frames[Math.floor(frames.length / 2)].toFixed(1),
  p95: +frames[Math.floor(frames.length * 0.95)].toFixed(1),
  max: +frames[frames.length - 1].toFixed(1),
};

await page.screenshot({path: '/tmp/pw-check/light.png'});

// 3. Тултип на hover
const over = await page.locator('.cpu-chart .uplot .u-over').boundingBox();
await page.mouse.move(over.x + over.width * 0.6, over.y + over.height * 0.4);
await page.waitForTimeout(400);
report.tooltipShown = await page.evaluate(() => {
  const t = document.querySelector('.cpu-chart .yagr-tooltip, .cpu-chart [class*="tooltip"]');
  return t ? getComputedStyle(t).display !== 'none' && t.textContent.trim().length > 0 : false;
});
await page.screenshot({path: '/tmp/pw-check/light-hover.png'});
await page.mouse.move(0, 0);

// 4. Ресайз контейнера
await page.setViewportSize({width: 960, height: 620});
await page.waitForTimeout(700);
report.sizeSmall = await boxes();
await page.setViewportSize({width: 1440, height: 1000});
await page.waitForTimeout(700);
report.sizeBig = await boxes();

// 5. Смена темы ОС: пересоздание без дублей; цвет поверхности карточки
await page.emulateMedia({colorScheme: 'dark'});
await page.waitForTimeout(900);
report.uplotCountDark = await page.locator('.cpu-chart .uplot').count();
report.themeClassDark = await page.locator('.cpu-chart.yagr_theme_dark').count();
report.cardBgDark = await page.evaluate(() => getComputedStyle(document.querySelector('.cpu-card')).backgroundColor);
await page.waitForTimeout(2500);
await page.screenshot({path: '/tmp/pw-check/dark.png'});

// 6. Возврат в светлую
await page.emulateMedia({colorScheme: 'light'});
await page.waitForTimeout(900);
report.uplotCountBackLight = await page.locator('.cpu-chart .uplot').count();
report.cardBgLight = await page.evaluate(() => getComputedStyle(document.querySelector('.cpu-card')).backgroundColor);

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
if (alive) await browser.close();

