  seen.push({url: route.request().url(), rawLen: raw.length, bodyLen: body.length, hasCpuCard: body.includes('cpu-card')});
  await route.fulfill({response, body, contentType: 'text/css'});
});
const page = await context.newPage();
await page.goto('http://127.0.0.1:5180/', {waitUntil: 'load'});
await page.waitForTimeout(1500);
