console.log(JSON.stringify(await page.evaluate(() => [...document.styleSheets].map((s) => ({href: s.href, rules: (() => { try { return s.cssRules.length; } catch (e) { return 'ERR ' + e.message; } })()}))), null, 1));
console.log('html links:', await page.evaluate(() => [...document.querySelectorAll('link[rel=stylesheet],style')].map((e) => e.tagName + ' ' + (e.getAttribute('href') || e.textContent.slice(0, 60)))));
await browser.close();
EOF
