cd /tmp/pw-check && cat > sheets2.mjs <<'EOF'
import {chromium} from 'playwright';
const mode = process.argv[2];
const browser = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
let alive = true;
browser.on('disconnected', () => { alive = false; });
const context = await browser.newContext({viewport: {width: 1280, height: 800}, locale: 'ru-RU'});
await context.route((url) => url.hostname !== '127.0.0.1', (route) => route.abort());
if (mode === 'strip') {
  await context.route(/\.css(\?|$)/, async (route) => {
    const response = await route.fetch();
    const body = (await response.text()).replace(/@import[^;]*;/g, '').replace(/@font-face\s*\{[^}]*\}/g, '');
    await route.fulfill({body, status: 200, headers: {'content-type': 'text/css; charset=utf-8'}});
  });
}
const page = await context.newPage();
await page.goto('http://127.0.0.1:5180/', {waitUntil: 'load', timeout: 30000}).catch((e) => console.log('goto err', e.message.split('\n')[0]));
await page.waitForTimeout(1500);
console.log(mode, 'alive=', alive, JSON.stringify(await page.evaluate(() => [...document.styleSheets].map((s) => { try { return s.cssRules.length; } catch (e) { return -1; } }))));
if (alive) console.log('canvas', await page.evaluate(() => { const c = document.querySelector('.cpu-chart canvas'); return c ? [c.width, c.height] : null; }));
if (alive) await browser.close();
EOF
export LD_LIBRARY_PATH=$(find /tmp/chrome-libs/root -name "*.so*" -printf "%h\n" | sort -u | paste -sd:); for m in passthrough strip; do timeout 90 node sheets2.mjs $m 2>&1 | grep -E "alive|canvas|err" | head -3; done

