import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu']});
const context = await browser.newContext({viewport: {width: 1280, height: 800}, locale: 'ru-RU', colorScheme: 'dark'});
await context.route((url) => url.hostname !== '127.0.0.1', (route) => route.abort());
const page = await context.newPage();
await page.goto('http://127.0.0.1:5180/', {waitUntil: 'load'});
await page.waitForTimeout(1500);
console.log(JSON.stringify(await page.evaluate(() => {
  const bg = (sel) => { const e = document.querySelector(sel); if (!e) return null; const cs = getComputedStyle(e); return {sel, bg: cs.backgroundColor, cls: e.className.toString().slice(0, 80)}; };
  const rules = [];
  for (const sheet of document.styleSheets) { try { for (const r of sheet.cssRules) { if (r.selectorText && /cpu-chart|yagr\b|\.yagr/.test(r.selectorText) && /background/.test(r.cssText)) rules.push(r.cssText.slice(0, 140)); } } catch (e) {} }
  return [bg('.cpu-card'), bg('.cpu-chart'), bg('.cpu-chart .uplot'), bg('.cpu-chart .u-wrap'), bg('.cpu-chart .u-over'), {yagrRules: rules}];
}), null, 1));
await browser.close();
EOF
