1	import {useEffect, useRef} from 'react';
2	import Yagr, {
3	  type AreaSeriesOptions,
4	  type ExtendedSeriesOptions,
5	  type MinimalValidConfig,
6	} from '@gravity-ui/yagr';
7	import '@gravity-ui/yagr/index.css';
8	import {useThemeType} from '@gravity-ui/uikit';
9	
10	import {CHART_PALETTE, type ChartPalette, type ChartThemeType} from './chartPalette';
11	import type {CpuFeed} from './cpuFeed';
12	
13	const SERIES_ID = 'cpu';
14	const Y_TICKS = [0, 25, 50, 75, 100];
15	// Окно — сутки: достаточно часов и минут без секунд.
16	const HOUR_MINUTE = new Intl.DateTimeFormat('ru', {hour: '2-digit', minute: '2-digit'});
17	
18	function axisStyle(palette: ChartPalette) {
19	  return {
20	    stroke: palette.axisText,
21	    grid: {show: true, stroke: palette.grid, width: 1},
22	    ticks: {show: true, stroke: palette.axisBaseline, width: 1, size: 4},
23	  };
24	}
25	
26	function cpuSeries(
27	  palette: ChartPalette,
28	  values: number[],
29	): AreaSeriesOptions & ExtendedSeriesOptions {
30	  return {
31	    id: SERIES_ID,
32	    name: 'Загрузка CPU',
33	    type: 'area',
34	    data: values,
35	    // Для area: color — заливка, lineColor/lineWidth — линия поверх.
36	    color: palette.seriesFill,
37	    lineColor: palette.seriesLine,
38	    lineWidth: 2,
39	    formatter: (value) => (value === null ? '—' : `${Number(value).toFixed(1)}%`),
40	  };
41	}
42	
43	function buildConfig(
44	  palette: ChartPalette,
45	  theme: ChartThemeType,
46	  times: number[],
47	  values: number[],
48	): MinimalValidConfig {
49	  return {
50	    chart: {
51	      appearance: {theme, locale: 'ru'},
52	      // Ресайз ведём сами (см. эффект ниже): встроенный debounce Yagr не отменяется в dispose().
53	      size: {adaptive: false},
54	      // Таймстемпы в миллисекундах.
55	      timeMultiplier: 1,
56	      // Для потока в реальном времени зум по умолчанию мешает: авто-диапазон сбрасывает его.
57	      select: {zoom: false},
58	    },
59	    legend: {show: false},
60	    tooltip: {show: true},
61	    // Курсор: вертикальный hairline к ближайшей точке по X; маркер на линии — 8px.
62	    cursor: {
63	      markersSize: 8,
64	      x: {visible: true, style: `1px solid ${palette.crosshair}`},
65	      y: {visible: false},
66	    },
67	    markers: {show: false},
68	    scales: {y: {min: 0, max: 100}},
69	    axes: {
70	      x: {
71	        ...axisStyle(palette),
72	        values: (_u, ticks) => ticks.map((t) => HOUR_MINUTE.format(t)),
73	      },
74	      y: {
75	        ...axisStyle(palette),
76	        splits: Y_TICKS,
77	        values: (_u, splits) => splits.map((v) => `${v}%`),
78	      },
79	    },
80	    timeline: times,
81	    series: [cpuSeries(palette, values)],
82	  };
83	}
84	
85	export interface CpuChartProps {
86	  feed: CpuFeed;
87	}
88	
89	export function CpuChart({feed}: CpuChartProps) {
90	  const themeType = useThemeType();
91	  const hostRef = useRef<HTMLDivElement>(null);
92	
93	  useEffect(() => {
94	    const host = hostRef.current;
95	    if (!host) {
96	      return;
97	    }
98	
99	    const palette = CHART_PALETTE[themeType];
100	    const {times, values} = feed.getHistory();
101	    const chart = new Yagr(host, buildConfig(palette, themeType, times, values));
102	
103	    // Новые сэмплы дописываются в скользящее окно без пересоздания графика.
104	    const unsubscribe = feed.subscribe(({time, value}) => {
105	      chart.setSeries([time], [{id: SERIES_ID, data: [value]}], {
106	        incremental: true,
107	        splice: true,
108	      });
109	    });
110	
111	    // Размер берём из контейнера; перерисовка — один раз за кадр.
112	    let frame = 0;
113	    const observer = new ResizeObserver(() => {
114	      if (frame) {
115	        return;
116	      }
117	      frame = requestAnimationFrame(() => {
118	        frame = 0;
119	        chart.reflow();
120	      });
121	    });
122	    observer.observe(host);
123	
124	    return () => {
125	      observer.disconnect();
126	      if (frame) {
127	        cancelAnimationFrame(frame);
128	      }
129	      unsubscribe();
130	      chart.dispose();
131	    };
132	  }, [feed, themeType]);
133	
134	  return <div ref={hostRef} className="cpu-chart" />;
135	}
136

